const SitePlan={
 level:'overview',zoom:100,selectedBuilding:1,
 buildings:[{id:1,x:352,y:455,w:270,h:128},{id:2,x:631,y:455,w:305,h:128},{id:3,x:352,y:328,w:270,h:124},{id:4,x:631,y:328,w:276,h:124},{id:5,x:452,y:235,w:170,h:90},{id:6,x:633,y:205,w:252,h:120}],
 cats:[{id:1,x:403},{id:2,x:453},{id:3,x:503},{id:4,x:553},{id:5,x:603},{id:6,x:703},{id:7,x:753},{id:8,x:803},{id:9,x:853}],
 healthColors:[
  {status:'กรงว่าง',color:'#f1f4ee'},
  {status:'ปกติ',color:'#79bf8c'},
  {status:'ยังไม่ประเมิน',color:'#b9c4cc'},
  {status:'เฝ้าระวัง',color:'#f0c45d'},
  {status:'อยู่ระหว่างดูแลรักษา',color:'#ed9b5f'},
  {status:'แยกดูแล',color:'#d9778f'}
 ],
 cageHealth(animals){
  if(!animals.length)return this.healthColors[0];
  const rank=status=>Math.max(2,this.healthColors.findIndex(x=>x.status===status));
  const index=animals.reduce((best,a)=>Math.max(best,a.status==='ปกติ'?1:rank(a.status)),1);
  return this.healthColors[index];
 },
 building(b){
  const layout=Care.layoutFor(b.id),capacity=Care.kennelsFor(b.id).length,label=`คอกสุนัข ${b.id}${b.id===5?' (คอกคลินิก)':''}`;
  const count=state.animals.filter(a=>a.kennel.startsWith(`D${b.id}-`)).length;
  const gap=12,rowHeight=(b.h-50-(layout.rows.length-1)*gap)/layout.rows.length;
  const rows=layout.rows.map((r,rowIndex)=>{
   const y=b.y+31+rowIndex*(rowHeight+gap),width=b.w-28-(b.id===2&&r==='B'?58:0),step=width/layout.counts[r];
   const cells=Array.from({length:layout.counts[r]},(_,i)=>{
    const number=String(i+1).padStart(2,'0'),code=`D${b.id}-${r}${number}`,animals=state.animals.filter(a=>a.kennel===code),health=this.cageHealth(animals);
    const detail=animals.length?animals.map(a=>`${a.name}: ${a.status||'ยังไม่ประเมิน'}`).join(' · '):'กรงว่าง';
    return `<g class="overview-cage" role="button" tabindex="0" data-plan="kennel" data-code="${code}" data-status="${health.status}" aria-label="${code} · ${esc(detail)}"><title>${code} · ${esc(detail)}</title><rect x="${b.x+17+i*step}" y="${y}" width="${step-1.3}" height="${rowHeight}" rx="1.5" style="fill:${health.color}"/><text x="${b.x+17+i*step+(step-1.3)/2}" y="${y+rowHeight/2+2.5}">${number}</text></g>`;
   }).join('');
   return `<text class="overview-row-label" x="${b.x+8}" y="${y+rowHeight/2+3}">${r}</text>${cells}${rowIndex<layout.rows.length-1?`<path class="zone-walk" d="M${b.x+17} ${y+rowHeight+gap/2}H${b.x+b.w-12}"/>`:''}`;
  }).join('');
  return `<g class="site-zone active" role="group" aria-label="${label}"><g class="site-building-header" role="button" tabindex="0" data-plan="building" data-building="${b.id}" aria-label="${label} เปิด ${capacity} กรง"><title>${label} · ${count} ตัว · ${capacity} กรง</title><rect class="zone-shell" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" rx="3"/><text class="zone-label" x="${b.x+b.w/2}" y="${b.y+20}">${b.id===5?'คอกคลินิก 5':'คอกสุนัข '+b.id}</text></g>${rows}<text class="zone-sub overview-building-count" x="${b.x+b.w/2}" y="${b.y+b.h-5}">${count} ตัว · ${capacity} กรง</text></g>`;
 },
 room(c){return `<g class="site-zone site-room" role="button" tabindex="0" data-plan="cat" data-room="${c.id}" aria-label="ห้องแมว ${c.id} ยังไม่ได้ตั้งค่าภายใน"><title>ห้องแมว ${c.id} — ยังไม่ได้ตั้งค่าภายใน</title><rect class="zone-shell" x="${c.x}" y="611" width="48" height="55"/><path class="zone-walk" d="M${c.x+2} 655H${c.x+46}"/><text x="${c.x+24}" y="634">ห้องแมว</text><text x="${c.x+24}" y="648" style="font-size:13px">${c.id}</text></g>`;},
 svg(){return `<svg class="site-svg" viewBox="210 65 820 660" xmlns="http://www.w3.org/2000/svg" aria-labelledby="site-map-title site-map-desc"><title id="site-map-title">ผังพื้นที่เลี้ยงสัตว์ส่วนสีเขียวของศูนย์ Nutrix</title><desc id="site-map-desc">อาคารสุนัข 1 และ 2 อยู่ด้านล่าง 3 และ 4 อยู่กลาง 5 และ 6 อยู่ด้านบน ห้องแมวเรียงด้านล่างสุด สีกรงย่อยแสดงสถานะสัตว์ปัจจุบัน เลือกกรงเพื่อดูสัตว์หรือชื่ออาคารเพื่อเปิดผังใหญ่</desc><defs><pattern id="kennel-lines" width="17" height="17" patternUnits="userSpaceOnUse"><rect width="17" height="17" fill="#c7dfb6"/><path d="M17 0V17" stroke="#a8c89a" stroke-width="1"/></pattern><pattern id="active-lines" width="17" height="17" patternUnits="userSpaceOnUse"><rect width="17" height="17" fill="#639c72"/><path d="M17 0V17" stroke="#8cb58c" stroke-width="1"/></pattern></defs><path class="site-boundary" d="M451 214L745 99Q837 58 878 120Q908 158 914 205L1009 701L247 699L230 641H320V387H352V327H451Z"/><path class="site-route" d="M337 394V681H978 M337 597H960 M626 211V592 M451 256L695 180 M908 212L978 677"/><path class="site-route-line" d="M337 394V681H978 M337 597H960 M626 211V592 M451 256L695 180 M908 212L978 677"/><text class="site-route-label" x="643" y="688">ทางเดินรอบอาคาร</text><rect class="site-pool" x="728" y="153" width="129" height="36" rx="3"/><text x="792" y="175" style="font-size:13px">สระว่ายน้ำ</text><path class="site-amenity" d="M746 120H842V149H728V138Z"/><text class="site-amenity-label" x="785" y="138">ห้องอาบน้ำตัดขน</text><rect class="site-amenity" x="842" y="120" width="26" height="29"/><text class="site-amenity-label" x="855" y="137" style="font-size:7px">ห้องน้ำ</text><rect class="site-amenity" x="699" y="157" width="27" height="32"/><text class="site-amenity-label" x="712" y="171" style="font-size:7px">อาบน้ำ</text>${this.buildings.map(b=>this.building(b)).join('')}<rect class="site-amenity" x="883" y="528" width="50" height="42"/><text class="site-amenity-label" x="908" y="546">ห้อง</text><text class="site-amenity-label" x="908" y="560">เก็บของ</text><rect class="site-amenity" x="353" y="611" width="48" height="55"/><text class="site-amenity-label" x="377" y="632">ห้องพัก</text><text class="site-amenity-label" x="377" y="647">พนักงาน</text>${this.cats.map(c=>this.room(c)).join('')}<rect class="site-amenity" x="653" y="611" width="48" height="55"/><text class="site-amenity-label" x="677" y="632">ห้องเตรียม</text><text class="site-amenity-label" x="677" y="647">อาหาร</text><rect class="site-amenity" x="903" y="611" width="49" height="55"/><path d="M903 639H952" stroke="#88b295"/><text class="site-amenity-label" x="927" y="631">ห้องน้ำ</text><text class="site-amenity-label" x="927" y="655">ห้องน้ำ</text></svg>`;},
 render(){return `<div class="page-heading site-map-heading"><div><div class="eyebrow">NUTRIX ANIMAL CENTER</div><h1>ผังพื้นที่ดูแลสัตว์</h1><p class="subtitle">สีกรงแสดงสถานะสัตว์ล่าสุด แตะกรงเพื่อดูสัตว์หรือแตะชื่ออาคารเพื่อเปิดผังใหญ่</p></div><button class="primary" data-plan="building" data-building="1">เปิดอาคารสุนัข 1 →</button></div><div class="site-layout"><section class="card site-plan-card"><div class="card-head"><div><h2>พื้นที่สีเขียว · ผังรวมศูนย์</h2><p>ตำแหน่งอาคารอ้างอิงจากผังที่คุณส่งมา</p></div>${tag('ผังโต้ตอบ')}</div><div class="plan-tools"><div class="legend overview-health-legend" aria-label="สีสถานะสัตว์ในกรง">${this.healthColors.map(h=>`<span><i class="cage-swatch" style="background:${h.color}"></i>${h.status}</span>`).join('')}</div><div class="plan-controls" aria-label="ปรับขนาดผัง"><button data-plan="zoom-out" aria-label="ย่อผัง">−</button><span id="plan-zoom-label">${this.zoom}%</span><button data-plan="zoom-in" aria-label="ขยายผัง">＋</button><button data-plan="zoom-reset">พอดีจอ</button></div></div><div class="plan-scroll" tabindex="0" aria-label="ผังศูนย์ เลื่อนดูพื้นที่หลังขยายได้"><div class="plan-canvas" style="width:${this.zoom}%">${this.svg()}</div></div><div class="plan-caption">แตะกรงเพื่อดูสัตว์ทุกตัว • แตะชื่ออาคารเพื่อเปิดผังใหญ่ • กด ＋ เพื่อขยายบนมือถือ<br>กรงที่มีหลายสถานะจะแสดงสีสถานะที่ต้องติดตามก่อน<br>รูปทรงและตำแหน่งเป็นผังสำหรับใช้งาน อ้างอิงพื้นที่สีเขียวในภาพ ไม่ใช่มาตราส่วนสำหรับงานก่อสร้าง</div></section><aside class="site-side"><section class="card panel-pad"><h3>อาคารสุนัขที่เปิดใช้งาน</h3><p>พร้อมทดลองเพิ่มสัตว์ ย้ายคอก และบันทึกการดูแล</p><div class="site-summary"><span>กรงทั้งหมด</span><b>${Care.kennels.length} กรง</b></div><div class="site-summary"><span>สัตว์ที่บันทึก</span><b>${state.animals.length} ตัว</b></div><div class="site-summary"><span>รูปแบบกรง</span><b>คอก 1, 3: 28 · คลินิก: 10</b></div><div class="site-building-shortcuts">${Care.buildings.map(id=>`<button class="secondary" data-plan="building" data-building="${id}">คอกสุนัข ${id}${id===5?' (คอกคลินิก)':''} →</button>`).join('')}</div></section><section class="card panel-pad"><h3>ห้องแมว 1–9</h3><p>วางตำแหน่งตามแนวด้านล่างของผัง รอยืนยันรูปแบบกรงภายในแต่ละห้อง</p><div class="site-room-shortcuts">${this.cats.map(c=>`<button data-plan="cat" data-room="${c.id}">ห้อง ${c.id}</button>`).join('')}</div></section><section class="card panel-pad"><h3>อ่านผังได้ตามสถานที่จริง</h3><p>ด้านบน: คอกสุนัข 5–6 และสระว่ายน้ำ<br>ตรงกลาง: คอกสุนัข 3–4<br>ด้านล่าง: คอกสุนัข 1–2<br>แนวล่างสุด: ห้องแมวและห้องเตรียมอาหาร</p><p>คอก 1 และ 3 คอกละ 28 กรง (ฝั่งละ 14) · คอก 2: A16 / B14 · คอก 4: A14 / B15 · คอก 6: A13 / B13 · คอก 5 (คอกคลินิก) 10 กรง แถวเดียว</p></section></aside></div>`;}
};
document.addEventListener('click',event=>{const el=event.target.closest('[data-plan]');if(!el)return;const action=el.dataset.plan;
 if(action==='building'){const id=Number(el.dataset.building);if(Care.buildings.includes(id)){SitePlan.selectedBuilding=id;SitePlan.level='building';view='map';if(dialog.open)dialog.close();render();window.scrollTo(0,0);}else openModal('คอกสุนัข '+id+' (คอกคลินิก)',`<div class="modal-body"><div class="notice">คอกคลินิก · ยังไม่ได้ตั้งค่ากรงภายใน</div><p class="side-copy">ต้องยืนยันจำนวนกรงและการแบ่งแถวของอาคารนี้ก่อนเปิดบันทึกสัตว์</p></div>`,`<div class="modal-actions"><button class="primary" data-action="close">กลับไปดูผัง</button></div>`);}
 else if(action==='kennel'){const code=el.dataset.code;if(Care.kennels.includes(code))openKennel(code);}
 else if(action==='cat'){openModal('ห้องแมว '+el.dataset.room,`<div class="modal-body"><div class="notice">วางตำแหน่งห้องตามผังแล้ว ยังไม่ได้ตั้งค่าภายในห้อง</div><p class="side-copy">ต้องยืนยันว่าเลี้ยงรวมในห้องหรือมีกรงย่อย ก่อนเปิดบันทึกสัตว์ในห้องนี้</p></div>`,`<div class="modal-actions"><button class="primary" data-action="close">กลับไปดูผัง</button></div>`);}
 else if(action==='overview'){view='map';SitePlan.level='overview';SitePlan.zoom=100;render();window.scrollTo(0,0);}
 else if(action.startsWith('zoom-')){SitePlan.zoom=action==='zoom-reset'?100:Math.min(600,Math.max(100,SitePlan.zoom+(action==='zoom-in'?50:-50)));const canvas=document.querySelector('.plan-canvas');if(canvas)canvas.style.width=SitePlan.zoom+'%';const label=document.getElementById('plan-zoom-label');if(label)label.textContent=SitePlan.zoom+'%';if(action==='zoom-reset'){const scroll=document.querySelector('.plan-scroll');scroll?.scrollTo(0,0);}}
});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('g[data-plan][role="button"]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
